  {/* Local media tiles */}
  <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
    <div data-testid="local-mic-tile" className="rounded-lg border p-3 text-sm">
      <p>{micTrack?.enabled ? "Microphone (simulated): on" : "Microphone (simulated): off"}</p>
      {!micGranted && (
        <p className="text-xs text-zinc-500 dark:text-zinc-400">
          {flow.deviceReadiness.microphone === "denied"
            ? "Microphone blocked — microphone permission denied (real device state)."
            : flow.deviceReadiness.microphone === "unavailable"
              ? "Microphone unavailable — no usable device (real device state)."
              : "Microphone permission not decided — run the device check in the lobby."}
        </p>
      )}
    </div>
    <div data-testid="local-camera-tile" className="rounded-lg border p-3 text-sm">
      <p>{camTrack?.enabled ? "Camera (simulated): on" : "Camera (simulated): off"}</p>
      {!camGranted && (
        <p className="text-xs text-zinc-500 dark:text-zinc-400">
          {flow.deviceReadiness.camera === "denied"
            ? "Camera blocked — camera permission denied (real device state)."
            : flow.deviceReadiness.camera === "unavailable"
              ? "Camera unavailable — no usable device (real device state)."
              : "Camera permission not decided — run the device check in the lobby."}
        </p>
      )}
    </div>
  </div>

  {/* Remote participants from the scripted timeline */}
  <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
    {media.remoteParticipants.map((p) => (
      <div
        key={p.id}
        className="flex min-h-32 flex-col justify-between rounded-lg border bg-zinc-800 p-3 text-zinc-100 dark:bg-zinc-900"
        data-testid={`remote-participant-${p.id}`}
      >
        <p className="text-xs text-zinc-400">
          {p.name} (simulated remote)
        </p>
        <p className="text-sm">
          {p.audioEnabled ? "Mic (simulated): on" : "Mic (simulated): off"}
          {" · "}
          {p.videoEnabled ? "Camera (simulated): on" : "Camera (simulated): off"}
        </p>
      </div>
    ))}
  </div>

  {/* Controls — toggles only when the real permission is granted */}
  <div className="flex flex-wrap items-center gap-2" role="group" aria-label="Call controls (simulated)">
    <button
      type="button"
      data-testid="toggle-mic"
      onClick={() => controller.toggleMic()}
      disabled={!micGranted}
      title={micGranted ? undefined : "Microphone is not available (real device state)"}
      className="rounded-md border px-3 py-1.5 text-sm disabled:opacity-50"
    >
      Toggle mic (simulated)
    </button>
    <button
      type="button"
      data-testid="toggle-camera"
      onClick={() => controller.toggleCamera()}
      disabled={!camGranted}
      title={camGranted ? undefined : "Camera is not available (real device state)"}
      className="rounded-md border px-3 py-1.5 text-sm disabled:opacity-50"
    >
      Toggle camera (simulated)
    </button>
    <button
      type="button"
      data-testid="advance-timeline"
      onClick={() => controller.advanceTimeline()}
      disabled={media.timelineRemaining === 0}
      className="rounded-md border px-3 py-1.5 text-sm disabled:opacity-50"
    >
      Run next timeline event ({media.timelineRemaining} queued)
    </button>
    <button
      type="button"
      data-testid="leave-call"
      onClick={() => void controller.leave()}
      className="rounded-md bg-red-600 px-3 py-1.5 text-sm text-white hover:bg-red-700"
    >
      Leave (ends the simulated call)
    </button>
  </div>

  {/* Shared notes (local simulation binding) */}
  <CollaborativeNotesEditorView
    isLoading={false}
    value={notes.value}
    onChange={notes.handleChange}
    records={notes.records}
    isSyncing={notesCore.isSyncing}
    isSaving={notes.isSaving}
    pendingOperationCount={notesCore.pendingOperationCount}
    version={notesCore.version}
    notesPresent
    simulationLabel
  />

  {/* In-call prompts (scripted timeline) */}
  <InCallPromptsOverlayView
    prompts={prompts.map((p) => ({ id: p.id, content: p.content, tags: p.tags }))}
    activePromptId={prompts[0]?.id ?? null}
    onUse={onUse}
    onDismiss={onDismiss}
    onShow={() => undefined}
    onHide={() => undefined}
  />
</section>

// Lobby: honest not-probed device state before any check.
let html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("Local simulation");
expect(html).toContain("Not decided");

await controller.probeDevices(grantedSurface());
html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("permission granted");

// Lobby → active: journaled create + start, accepted exactly once.
await controller.join();
expect(controller.getSnapshot().phase).toBe("active");
html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("In call — local simulation");
expect(simulation.sentLifecycle).toEqual(["create", "start"]);

// Shared notes work inside the active phase (per-edit states intact):
// type, wait out the 500ms debounce, flush the microtasks.
vi.useFakeTimers();
notes!.handleChange("Agenda: ");
await vi.advanceTimersByTimeAsync(500);
vi.useRealTimers();
html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("Agenda:");
expect(html).toContain(">Saved<");
expect(simulation.notesDocContent()).toBe("Agenda: ");
expect(simulation.notesDocVersion()).toBe(1);

// Scripted timeline: advance through the deterministic steps until a
// remote participant joins, then the tile renders the simulated label.
let advanced = 0;
while (
  controller.media.getSnapshot().remoteParticipants.length === 0 &&
  controller.advanceTimeline()
) {
  advanced += 1;
}
expect(advanced).toBeGreaterThan(0);
html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("(simulated remote)");

// Active → ended: journaled end, accepted exactly once.
await controller.leave();
expect(controller.getSnapshot().phase).toBe("ended");
expect(simulation.sentLifecycle).toEqual(["create", "start", "end"]);
html = renderFlow(controller, simulation, (n) => (notes = n));
expect(html).toContain("Lifecycle journal receipt");

// EXACT journal outcomes: created once, started once, ended once.
const entries = controller.journalEntries();
expect(entries.map((e) => [e.operation, e.state, e.attempts])).toEqual([
  ["create", "accepted", 1],
  ["start", "accepted", 1],
  ["end", "accepted", 1],
]);
expect(controller.getSnapshot().summary?.endState).toBe("confirmed");

await controller.probeDevices({
  enumerateDevices: async () => [
    { kind: "audioinput" },
    { kind: "videoinput" },
  ],
  getUserMedia: async () => {
    const err = new Error("denied");
    err.name = "NotAllowedError";
    throw err;
  },
});
html = renderFlow(controller, simulation);
expect(html).toContain("permission denied");
expect(html).toContain("Blocked — permission denied");
// The honest state never claims readiness.
expect(html).not.toContain("permission granted");

// No media devices API at all (Node test reality, and browsers with
// the API disabled): the honest state is "unavailable", never success.
await controller.probeDevices(undefined);
const html = renderFlow(controller, simulation);
expect(html).toContain("Unavailable — no usable device");
expect(html).toContain("Media devices API is unavailable");
expect(html).not.toContain("permission granted");

// Devices missing from enumeration are equally honest.
await controller.probeDevices({
  enumerateDevices: async () => [],
  getUserMedia: async () => ({}),
});
const readiness = controller.getSnapshot().deviceReadiness;
expect(readiness.microphone).toBe("unavailable");
expect(readiness.camera).toBe("unavailable");
expect(readiness.detail).toContain("No microphone found");
expect(readiness.detail).toContain("No camera found");
void simulation;
